import yaml,glob,os,sys,json
R="C:/visual projects/reverse-kit/pipeline/_work/run_wol2/records"
def files():
    return sorted(glob.glob(R+"/**/*.yaml",recursive=True))
def load(f):
    return yaml.safe_load(open(f,encoding='utf-8'))
def items(d):
    for k in ('rules','catalog'):
        for it in d.get(k) or []:
            yield k,it
if __name__=="__main__":
    out=open(sys.argv[1],'w',encoding='utf-8')
    for f in files():
        d=load(f); b=os.path.relpath(f,R).replace('\\','/')
        for k,it in items(d):
            nm=json.dumps(it.get('numbers'),ensure_ascii=False)
            out.write(f"{b}|{it['id']}|{it.get('title') or it.get('own_name')}|{it.get('behavior')}|{nm}\n")
EOF
cd "$S" && python dump.py flat.txt && wc flat.txt; grep -ci "умнож\|множител" flat.txt; grep -ci "множител\|умнож\|×\|x[0-9]" flat.txt

