import json,re,sys
from dump import *
code=json.load(open('code_mult.json')); hits=json.load(open('hits.json'))
broad={'Player','Enemy','EnemyGlobalStatManager','PvpController','BasicMinion','Blob','ChaosMinion','Dove','FlameKnight','ThunderKnight','BlobRoller','WindMinion','SuperBlob','Seeker'}
want={(b,i):cl for b,i,cl in hits}
sel=[(b,i,[c for c in cl if c not in broad]) for (b,i),cl in want.items()]
sel=[s for s in sel if s[2]]
print(len(sel),file=sys.stderr)
cache={}
for b,i,cl in sel:
    d=cache.setdefault(b,load(R+'/'+b))
    for k,it in items(d):
        if it['id']==i:
            beh=(it.get('behavior') or '').replace('\n',' ')
            print('##',b,i,it.get('title') or it.get('own_name'),'| code:',{c:code[c] for c in cl})
            print('  B:',beh[:900])
            print('  N:',json.dumps(it.get('numbers'),ensure_ascii=False)[:500])
EOF
python rev.py > rev.txt; wc rev.txt

