import json,re,sys,collections
from dump import *
idx=json.load(open('C:/visual projects/reverse-kit/pipeline/_work/run_wol2/index/index.json',encoding='utf-8'))
names=set()
for t in idx['types']:
    names.add(t['name'])
    for m in t.get('members') or []: names.add(m['name'])
    names.add(t['file'])
for k in ('fields','methods'):
    for x in idx[k]: names.add(x.get('name'))
names.discard(None)
hump=re.compile(r'^(?:[A-Z][a-z0-9]+){2,}$|^[a-z]+(?:[A-Z][a-z0-9]*)+$|^[A-Za-z]+_[A-Za-z0-9_]+$')
ident=re.compile(r'[A-Za-z_][A-Za-z0-9_]*(?:\.cs)?')
def camel(w): return bool(hump.match(w)) and len(w)>3
def scan_text(s):
    res=[]
    for w in set(ident.findall(s or '')):
        if w.endswith('.cs') or camel(w) or (w in names and len(w)>3 and w[0].isupper() and not w.isupper() and False):
            res.append(w)
    return res
def public_fields(d):
    for f in ('goal',):
        if d.get(f): yield ('goal',None,d[f])
    for k in ('open_questions','acceptance'):
        for i,s in enumerate(d.get(k) or []): yield (k,None,s)
    for k,it in items(d):
        for f in ('title','own_name','behavior'):
            if it.get(f): yield (f,it['id'],it[f])
        for c in it.get('conditions') or []: yield ('conditions',it['id'],c)
if __name__=="__main__":
    cnt=collections.Counter(); recs=0
    out=[]
    for f in files():
        d=load(f); b=os.path.relpath(f,R).replace(chr(92),'/')
        for fld,i,s in public_fields(d):
            h=scan_text(s)
            if h:
                recs+=1
                for w in h: cnt[w]+=1
                out.append((b,i,fld,h))
    print('hits fields',recs,'distinct',len(cnt))
    print(cnt.most_common(80))
    json.dump(out,open('clean_hits.json','w'),ensure_ascii=False)
EOF
python clean.py

