import yaml,glob,re
def texts(d):
    for k in ('goal',):
        if d.get(k): yield k,d[k]
    for k in ('open_questions','acceptance'):
        for s in d.get(k) or []: yield k,s
    for sec in ('rules','catalog'):
        for it in d.get(sec) or []:
            for f in ('title','own_name','behavior'):
                if it.get(f): yield f"{sec}:{it['id']}:{f}",it[f]
            for c in it.get('conditions') or []: yield f"{sec}:{it['id']}:cond",c
checks={
 'doctor':lambda s: re.search(r'врач|доктор',s,re.I) and re.search(r'жетон|способност|аркан',s,re.I),
 'icethrow':lambda s: re.search(r'ледяной бросок|бросок',s,re.I) and re.search(r'неуязвим',s,re.I),
 'wall':lambda s: re.search(r'стен',s,re.I) and re.search(r'земл',s,re.I) and re.search(r'\b(10|25)\b',s),
 'gust':lambda s: re.search(r'порыв',s,re.I) and re.search(r'2\.75|2\.25|0\.75|1\.5|0\.6',s),
 'cam':lambda s: re.search(r'камер',s,re.I) and re.search(r'\b(25|26|14|15)\b',s) and re.search(r'предел|границ|лимит|ограничен',s,re.I),
}
for f in sorted(glob.glob('**/*.yaml',recursive=True)):
    d=yaml.safe_load(open(f,encoding='utf-8'))
    for loc,s in texts(d):
        for k,fn in checks.items():
            if fn(s): print(k,f.replace('\\','/'),loc,'::',s[:330].replace('\n',' '))
EOF

